#!/usr/bin/env bash
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
CHECK_RELEASES="${SCRIPT_DIR}/check-release-please-component-releases.sh"
TEST_ROOT="$(mktemp -d)"
trap 'rm -rf "$TEST_ROOT"' EXIT

fail() {
  echo "FAIL: $1" >&2
  exit 1
}

assert_contains() {
  local text=$1 expected=$2
  grep -Fq -- "$expected" <<<"$text" ||
    fail "expected output to contain: ${expected}"
}

expect_success() {
  local repo=$1 merge_base=$2 merge_head=$3 release_head=$4
  local output

  if ! output=$(
    cd "$repo"
    "$CHECK_RELEASES" "$merge_base" "$merge_head" "$release_head" 2>&1
  ); then
    echo "$output" >&2
    fail "expected release presence check to succeed"
  fi
  assert_contains \
    "$output" \
    "all intervening managed source changes are covered by release targets"
}

expect_failure() {
  local repo=$1 merge_base=$2 merge_head=$3 release_head=$4 expected=$5
  local output

  if output=$(
    cd "$repo"
    "$CHECK_RELEASES" "$merge_base" "$merge_head" "$release_head" 2>&1
  ); then
    fail "expected release presence check to fail"
  fi
  assert_contains "$output" "$expected"
}

setup_repo() {
  local name=$1
  REPO="${TEST_ROOT}/${name}"
  mkdir -p \
    "${REPO}/native/helper/src" \
    "${REPO}/native/runner/mitm-addon/src" \
    "${REPO}/native/runner/src" \
    "${REPO}/native/runner/tests" \
    "${REPO}/turbo/apps/api/src" \
    "${REPO}/turbo/apps/app/src" \
    "${REPO}/turbo/packages/shared/src" \
    "${REPO}/docs"

  printf 'helper runtime\n' >"${REPO}/native/helper/src/lib.rs"
  printf 'runner runtime\n' \
    >"${REPO}/native/runner/mitm-addon/src/runtime.py"
  printf 'runner library\n' >"${REPO}/native/runner/src/lib.rs"
  printf 'runner test\n' >"${REPO}/native/runner/tests/runtime.test.py"
  printf 'api runtime\n' >"${REPO}/turbo/apps/api/src/index.ts"
  printf 'app runtime\n' >"${REPO}/turbo/apps/app/src/index.ts"
  printf 'shared runtime\n' >"${REPO}/turbo/packages/shared/src/index.ts"
  printf 'documentation\n' >"${REPO}/docs/README.md"

  printf '%s\n' \
    '[workspace]' \
    'members = ["helper", "runner"]' \
    'resolver = "2"' \
    >"${REPO}/native/Cargo.toml"
  printf '%s\n' \
    '[package]' \
    'name = "helper"' \
    'version = "1.0.0"' \
    'edition = "2024"' \
    >"${REPO}/native/helper/Cargo.toml"
  printf '%s\n' \
    '[package]' \
    'name = "runner"' \
    'version = "1.0.0"' \
    'edition = "2024"' \
    '' \
    '[dev-dependencies]' \
    'helper = { path = "../helper" }' \
    >"${REPO}/native/runner/Cargo.toml"
  printf '%s\n' \
    '# This file is automatically @generated by Cargo.' \
    '# It is not intended for manual editing.' \
    'version = 4' \
    '' \
    '[[package]]' \
    'name = "helper"' \
    'version = "1.0.0"' \
    '' \
    '[[package]]' \
    'name = "runner"' \
    'version = "1.0.0"' \
    'dependencies = [' \
    ' "helper",' \
    ']' \
    >"${REPO}/native/Cargo.lock"

  printf '%s\n' \
    '{"name":"api","version":"1.0.0","dependencies":{"shared":"workspace:*"}}' \
    >"${REPO}/turbo/apps/api/package.json"
  printf '%s\n' \
    '{"name":"app","version":"1.0.0","dependencies":{"shared":"workspace:*"}}' \
    >"${REPO}/turbo/apps/app/package.json"
  printf '%s\n' \
    '{"name":"shared","version":"1.0.0"}' \
    >"${REPO}/turbo/packages/shared/package.json"

  printf '%s\n' \
    '{"packages":{"native/helper":{"release-type":"rust"},"native/runner":{"release-type":"rust","component":"runner-rs"},"turbo/apps/api":{"release-type":"node"},"turbo/apps/app":{"release-type":"node"},"turbo/packages/shared":{"release-type":"node"}},"plugins":[{"type":"node-workspace","alwaysLinkLocal":true},{"type":"cargo-workspace","cargoWorkspacePath":"./native/"}]}' \
    >"${REPO}/release-please-config.json"
  printf '%s\n' \
    '{"native/helper":"1.0.0","native/runner":"1.0.0","turbo/apps/api":"1.0.0","turbo/apps/app":"1.0.0","turbo/packages/shared":"1.0.0"}' \
    >"${REPO}/.release-please-manifest.json"

  git -C "$REPO" init -q -b main
  git -C "$REPO" config user.email test@example.com
  git -C "$REPO" config user.name Test
  git -C "$REPO" add --all
  git -C "$REPO" commit -qm "baseline"
  BASE=$(git -C "$REPO" rev-parse HEAD)
}

update_manifest() {
  local repo=$1 filter=$2
  local output="${repo}/.release-please-manifest.next.json"

  jq -c "$filter" "${repo}/.release-please-manifest.json" >"$output"
  mv "$output" "${repo}/.release-please-manifest.json"
}

create_release_head() {
  local repo=$1 branch=$2 filter=$3

  git -C "$repo" switch -q -C "$branch" "$BASE"
  update_manifest "$repo" "$filter"
  git -C "$repo" add .release-please-manifest.json
  git -C "$repo" commit -qm "chore: release main"
  git -C "$repo" rev-parse HEAD
}

create_merge_head() {
  local repo=$1 branch=$2 merge_base=$3 filter=$4

  git -C "$repo" switch -q -C "$branch" "$merge_base"
  update_manifest "$repo" "$filter"
  git -C "$repo" add .release-please-manifest.json
  git -C "$repo" commit -qm "chore: release main"
  git -C "$repo" rev-parse HEAD
}

